function format({order}) {
 const str=(v,name)=>{if(typeof v!=='string')throw Error('Missing '+name);return v},escape=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
 if(!order||typeof order!=='object'||Array.isArray(order)||!Number.isSafeInteger(order.id)||order.id<=0)throw Error('Invalid order ID');
 const total=str(order.total,'total'),currency=str(order.currency,'currency');if(!/^-?\d+(?:\.\d+)?$/.test(total)||!/^[A-Z]{3}$/.test(currency))throw Error('Invalid total or currency');
 const raw=str(order.date_created_gmt,'creation date'),match=/^(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d)Z?$/.exec(raw);if(!match)throw Error('Invalid GMT creation date');const dt=new Date(match[1]+'Z');if(!Number.isFinite(dt.getTime())||dt.toISOString().slice(0,19)!==match[1])throw Error('Invalid GMT creation date');
 if(!order.billing||typeof order.billing!=='object'||Array.isArray(order.billing)||!Array.isArray(order.line_items))throw Error('Missing billing or line items');const b=order.billing,name=str(b.first_name,'first name')+' '+str(b.last_name,'last name'),city=str(b.city,'city'),phone=str(b.phone,'phone'),note=str(order.customer_note,'customer note');
 const products=order.line_items.map(item=>{if(!item||typeof item.name!=='string'||!Number.isSafeInteger(item.quantity)||item.quantity<0)throw Error('Invalid line item');return '🔹 '+escape(item.name)+'<b> ('+item.quantity+' items)</b>';}).join('
');
 const text='🆔 <b>Order ID:</b> '+order.id+'

👦🏻 <b>Customer Name:</b> '+escape(name)+'

💵 <b>Amount:</b> '+escape(total)+' '+escape(currency)+'

📅 <b>Order Date:</b>
➖ '+match[1].replace('T',' ')+' UTC

🏙 <b>City:</b> '+escape(city)+'

📞 <b>Phone:</b> '+escape(phone)+'

✍🏻 <b>Order Note:</b>
'+escape(note||'No notes')+'

📦 <b>Ordered Products:</b>

'+products;
 if(text.length>4096)throw Error('Order notice exceeds the Telegram message limit');return {text};
}

return {json:format({order:$("Order updated").item.json})};
